window.addEventListener('resize',positionLauncher);positionLauncher();
let observedChat=appHost.currentChatId();
// Follow Marinara's open chat only while SIDE B is still on it; never interrupt a running generation.
const watchChat=window.setInterval(()=>{const next=appHost.currentChatId();if(next===observedChat)return;const old=observedChat;observedChat=next;if(chatId!==old||busy||generationPreparing)return;rememberReferences();chatId=next;workResults.clear();if(opened)refresh();},1000);
appHost.onCleanup(()=>{clearInterval(watchChat);window.removeEventListener('resize',positionLauncher);launchHost.remove();});
